  #[local] Notation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).

  Section Call.
    Context {fx : FPState}.
    Variables (A : AS MI) (s : LibIface.SX ST) (R : bvmap 5 word) (M : mem) (model : Model).
    Variables (sp ret S ds p pcons icount err : Z) (K : TSet).
    Hypothesis CB : callB MI ST A s R M model sp ret S.
    Hypothesis HS : PDIAG_STK <= S.
    Hypothesis ROC : ro_clear Ly.L M.
    Hypothesis Ha0 : getr R 10%bv = Z_to_bv 64 ds.
    Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 p.
    Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 (err mod 2 ^ 64).
    Hypothesis Herr : - 2 ^ 31 <= err < 0.
    Hypothesis Hp8 : fld SEGS M (p + 8) 8 pcons.
    Hypothesis Hp80 : fld SEGS M (p + 80) 8 icount.
    Hypothesis Hp0 : 0 <= p.
    Hypothesis Hp88 : p + 88 <= 2 ^ 47.
    Hypothesis HPW : forall a, zwin p (p + 88) a -> ~ zwin (sp - S) sp a.
    Hypothesis Hic : 0 <= icount < 2 ^ 63.
    Hypothesis Hds : above_sp MI A sp ds 392 /\ ds mod 8 = 0 /\ mdef M ds 392.
    Hypothesis Hcons : obj_ok MI A sp S pcons 48 /\ fld SEGS M (pcons + 32) 8 0.
    Hypothesis Hpc_hi : pcons + 48 <= 2 ^ 47.
    Hypothesis Hpc16 : pcons mod 16 = 0.
    Hypothesis DISJ : forall a, zwin ds (ds + 392) a -> ~ zwin pcons (pcons + 48) a.
    Hypothesis CONT : forall A' R' M' model' B,
        retB MI ST A' s R R' M' model model' ->
        ds_rep MI A' M' ds err 0 B ->
        blk_xfer [] B (live MI A) (live MI A') ->
        eff MI A A' M M' (sp - S, sp) (ds_foot ds B) ->
        srealizes SEGS (cfg fx R' ret M' model') K.

    Lemma pdiag_main : srealizes SEGS (cfg fx R A_PDIAGE M model) K.
Proof using AC RRND MI ST DN fx A s R M model sp ret S ds p pcons icount err K CB HS ROC Ha0 Ha1 Ha2 Herr Hp8 Hp80 Hp0 Hp88 HPW Hic Hds Hcons Hpc_hi Hpc16 DISJ CONT.
